extern "C" unsigned strlen(const char *);

class stringx {
public:
  struct buffer { int refs; int alloc; int char_length; };
  buffer *my_buf;
  stringx();
  stringx(const stringx&);
  ~stringx();
  void make_room(int);
  void append(const stringx&);
  void append(const char *, int);
};

inline stringx operator+(const stringx& lhs, const char *rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

inline stringx operator+(const stringx& lhs, const stringx& rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

class script_instance { char pad[4]; stringx name; public: const stringx& get_name() const { return name; } };
class vm_executable { char pad[12]; stringx fullname; public: const stringx& get_fullname() const { return fullname; } };
class vm_thread { script_instance *inst; const vm_executable *ex; public: script_instance *get_instance() const { return inst; } const vm_executable *get_executable() const { return ex; } };

class vm_stack {
public:
  int salloc; char *buffer; char *SP; vm_thread *my_thread;
  void pop(int n) { SP -= n; }
  bool push(const char *, int);
  vm_thread *get_thread() const { return my_thread; }
};

class widget {
public:
  enum rhw_layer_e { RHW0 };
  static float rhw_2d_val[];
  static float rhw_layer_ranges[][2];
  static rhw_layer_e rhw_2d_layer;
  static rhw_layer_e last_rhw_2d_layer;
  static void set_rhw_2d_layer(rhw_layer_e layer) { last_rhw_2d_layer = rhw_2d_layer; rhw_2d_layer = layer; rhw_2d_val[rhw_2d_layer] = rhw_layer_ranges[rhw_2d_layer][0]; }
  static void restore_last_rhw_2d_layer() { rhw_2d_layer = last_rhw_2d_layer; }
};
class background_widget : public widget { char data[324]; public: background_widget(const char *, widget *, short, short, const stringx&); };
class script_widget_holder_t;
class game { char pad[60]; script_widget_holder_t *holder; public: script_widget_holder_t *get_script_widget_holder() const { return holder; } };
extern game *g_game_ptr;
void *operator new(unsigned, unsigned, const char *, int);
void error(const stringx&);

typedef const stringx *vm_str_t;
typedef background_widget *vm_bitmap6_widget_t;
class script_library_class { public: class function { public: enum entry_t { FIRST_ENTRY, RECALL_ENTRY }; }; };

#define NEW new(0,__FILE__,__LINE__)
#define SLF_PARMS stack.pop(sizeof(parms_t)); parms_t* parms = (parms_t*)stack.SP
#define SLF_RETURN if (!stack.push((char*)&result,sizeof(result))) error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname())
#define SLF_DONE return true

class slf_create_bitmap6_widget_t : public script_library_class::function
{
public:
  struct parms_t { vm_str_t filename; };
  virtual bool operator ()(vm_stack &stack, entry_t entry)
  {
    SLF_PARMS;

    widget::set_rhw_2d_layer( widget::RHW0 );
    vm_bitmap6_widget_t result = NEW background_widget( "script bitmap6 widg", (widget*)(g_game_ptr->get_script_widget_holder()), 0, 0, *parms->filename );
    widget::restore_last_rhw_2d_layer();

    SLF_RETURN;
    SLF_DONE;
  }
};
